    payload = task.model_dump()
    deps = payload.pop("predecessors", payload.pop("dependencies", []))
    db_task = models.Task(**payload, dependencies=deps, project_id=project_id)
    db.add(db_task)
    db.commit()
    db.refresh(db_task)
    return db_task

