    if db_task:
        data = task_in.model_dump(exclude_unset=True)
        deps = data.pop("predecessors", data.pop("dependencies", None))
        for var, value in data.items():
            setattr(db_task, var, value)
        if deps is not None:
            db_task.dependencies = deps
        db.add(db_task)
        db.commit()
        db.refresh(db_task)
    return db_task

