          />
        </Box>
      </DialogContent>
      <DialogActions>
        <Button onClick={onClose} disabled={createProjectMutation.isPending}>
          Cancel
        </Button>
        <Button 
          onClick={handleSubmit} 
          variant="contained"
          disabled={createProjectMutation.isPending || !name.trim()}
        >
          {createProjectMutation.isPending ? <CircularProgress size={24} /> : 'Create'}
        </Button>
      </DialogActions>
    </Dialog>
